using System.Collections.Generic;
using UnityEngine;

namespace Wildbond
{
    /// <summary>
    /// Runtime lookup for all content definitions. Loads ScriptableObject assets from
    /// Resources/Content (generated by Wildbond > Generate Content). If none exist it falls
    /// back to building them in memory from ContentSeed so the game always runs.
    /// </summary>
    public static class ContentDB
    {
        public static readonly Dictionary<string, ItemDef> Items = new Dictionary<string, ItemDef>();
        public static readonly Dictionary<string, RecipeDef> Recipes = new Dictionary<string, RecipeDef>();
        public static readonly Dictionary<string, AbilityDef> Abilities = new Dictionary<string, AbilityDef>();
        public static readonly Dictionary<string, TraitDef> Traits = new Dictionary<string, TraitDef>();
        public static readonly Dictionary<string, SpeciesDef> Species = new Dictionary<string, SpeciesDef>();
        public static readonly Dictionary<string, BuildingDef> Buildings = new Dictionary<string, BuildingDef>();

        public static readonly List<SpeciesDef> SpeciesList = new List<SpeciesDef>();
        public static readonly List<RecipeDef> RecipeList = new List<RecipeDef>();
        public static readonly List<BuildingDef> BuildingList = new List<BuildingDef>();
        public static readonly List<TraitDef> TraitList = new List<TraitDef>();
        public static readonly List<SpeciesDef> Starters = new List<SpeciesDef>();

        public static bool Ready { get; private set; }

        public static void Init()
        {
            if (Ready) return;
            var bundle = new ContentSeed.Bundle();
            bundle.items.AddRange(Resources.LoadAll<ItemDef>("Content"));
            bundle.recipes.AddRange(Resources.LoadAll<RecipeDef>("Content"));
            bundle.abilities.AddRange(Resources.LoadAll<AbilityDef>("Content"));
            bundle.traits.AddRange(Resources.LoadAll<TraitDef>("Content"));
            bundle.species.AddRange(Resources.LoadAll<SpeciesDef>("Content"));
            bundle.buildings.AddRange(Resources.LoadAll<BuildingDef>("Content"));

            if (bundle.species.Count == 0 || bundle.items.Count == 0)
            {
                Debug.Log("[ContentDB] No content assets found - building content from ContentSeed in memory.");
                bundle = ContentSeed.Build();
            }
            else MergeMissing(bundle, ContentSeed.Build());
            Index(bundle);
            FishJobs.Apply();   // the Fishing job is derived from each species (Tide / lives by water), not stored in its asset
            Ready = true;
        }

        /// <summary>Seed entries without a generated asset yet (new content) are added in memory.</summary>
        static void MergeMissing(ContentSeed.Bundle into, ContentSeed.Bundle seed)
        {
            Merge(into.items, seed.items, x => x.id);
            Merge(into.recipes, seed.recipes, x => x.id);
            Merge(into.abilities, seed.abilities, x => x.id);
            Merge(into.traits, seed.traits, x => x.id);
            Merge(into.species, seed.species, x => x.id);
            Merge(into.buildings, seed.buildings, x => x.id);
        }

        static void Merge<T>(List<T> into, List<T> seed, System.Func<T, string> id)
        {
            var have = new HashSet<string>();
            foreach (var x in into) have.Add(id(x));
            foreach (var x in seed) if (!have.Contains(id(x))) into.Add(x);
        }

        static void Index(ContentSeed.Bundle b)
        {
            foreach (var x in b.items) Items[x.id] = x;
            foreach (var x in b.recipes) { Recipes[x.id] = x; RecipeList.Add(x); }
            foreach (var x in b.abilities) Abilities[x.id] = x;
            foreach (var x in b.traits) { Traits[x.id] = x; TraitList.Add(x); }
            foreach (var x in b.species) { Species[x.id] = x; SpeciesList.Add(x); if (x.starter) Starters.Add(x); }
            foreach (var x in b.buildings) { Buildings[x.id] = x; BuildingList.Add(x); }
            SpeciesList.Sort((a, c) => a.dexNumber.CompareTo(c.dexNumber));
            Starters.Sort((a, c) => a.dexNumber.CompareTo(c.dexNumber));
            RecipeList.Sort((a, c) => a.unlockLevel != c.unlockLevel ? a.unlockLevel.CompareTo(c.unlockLevel) : string.CompareOrdinal(a.id, c.id));
            BuildingList.Sort((a, c) => a.unlockLevel != c.unlockLevel ? a.unlockLevel.CompareTo(c.unlockLevel) : string.CompareOrdinal(a.id, c.id));
        }

        public static ItemDef Item(string id) => id != null && Items.TryGetValue(id, out var d) ? d : null;
        public static SpeciesDef Sp(string id) => id != null && Species.TryGetValue(id, out var d) ? d : null;
        public static AbilityDef Ability(string id) => id != null && Abilities.TryGetValue(id, out var d) ? d : null;
        public static TraitDef Trait(string id) => id != null && Traits.TryGetValue(id, out var d) ? d : null;
        public static BuildingDef Building(string id) => id != null && Buildings.TryGetValue(id, out var d) ? d : null;
        public static string ItemName(string id) { var d = Item(id); return d != null ? d.displayName : id; }
    }
}
